import * as THREE from './vendor/three.module.js';
import {TangenzialeRace} from './tangenziale-race.js';

const TARGET_METRES=3400,MIN_METRES=2200,OFFROAD_LIMIT=18;
const HIGH_RAMP_FRACTIONS=[.18,.48,.82],FAKE_RAMP_FRACTIONS=[.33,.66],OBSTACLE_FRACTIONS=[.27,.53,.76];

const yawAt=(path,i)=>{const a=path[Math.max(0,i-1)],b=path[Math.min(path.length-1,i+1)];return Math.atan2(b.x-a.x,b.z-a.z);};
const lateral=(p,yaw,offset)=>({x:p.x+Math.cos(yaw)*offset,z:p.z-Math.sin(yaw)*offset});
const heightAt=(game,p,x=p.x,z=p.z)=>{const y=p?.road?game.terrain.roads?.sample?.(p.road,x,z):NaN;return Number.isFinite(y)?y+.05:game.terrain.height(x,z,p.y);};
const progress=(r,i)=>Math.max(0,(r.samples.cumulative[i]||0)-r.startDistance);
function safeIndex(samples,start,end,fraction){const target=Math.round(start+(end-start)*fraction);for(let d=0;d<=12;d++)for(const sign of d?[1,-1]:[1]){const i=target+d*sign;if(i<=start+5||i>=end-3)continue;const road=samples[i]?.road;if(road&&!road.tunnel&&!road.crossing&&!road.b&&!(Number(road.layer)>0))return i;}return Math.max(start+6,Math.min(end-4,target));}
function nearest2D(actor,samples,hint){let best=Math.max(0,Math.min(samples.length-1,hint||0)),distance=Infinity;const lo=Math.max(0,best-12),hi=Math.min(samples.length-1,best+18);for(let i=lo;i<=hi;i++){const d=Math.hypot(actor.x-samples[i].x,actor.z-samples[i].z);if(d<distance){distance=d;best=i;}}if(distance>OFFROAD_LIMIT)for(let i=0;i<samples.length;i+=2){const d=Math.hypot(actor.x-samples[i].x,actor.z-samples[i].z);if(d<distance){distance=d;best=i;}}return {index:best,d:distance};}
function offsetPath(samples,offset,obstacles){return samples.map((p,i)=>{let shift=offset;for(const o of obstacles){const d=Math.abs(i-o.index);if(d<=4){const target=o.offset>=0?-1.65:1.65,blend=1-d/5;shift=offset+(target-offset)*blend;}}return {...p,...lateral(p,yawAt(samples,i),shift)};});}
function box(root,w,h,d,color){const mesh=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),new THREE.MeshStandardMaterial({color,roughness:.6}));mesh.castShadow=true;mesh.receiveShadow=true;root.add(mesh);return mesh;}
function rampVisual(root,r,fake=false){const g=new THREE.Group();g.position.set(r.x,r.baseY,r.z);g.rotation.y=r.yaw;const m=box(g,r.width,fake?.20:.24,r.length,fake?'#e5a039':'#d56e32');m.position.y=(r.rise||.25)/2;m.rotation.x=-Math.atan2(r.rise||.25,r.length);if(fake)for(const z of [-2.4,0,2.4]){const stripe=box(g,r.width*.88,.05,.52,'#161b20');stripe.position.set(0,.23,z);}root.add(g);}
function buildHighRamp(game,r,index,side){const p=r.samples[index],yaw=yawAt(r.samples,index),q=lateral(p,yaw,side*1.55),baseY=heightAt(game,p,q.x,q.z),width=5,length=10.5,rise=2.55,behind=length/2+4.6,s=Math.sin(yaw),c=Math.cos(yaw);return {kind:'tangenziale-race-ramp-high',tangenzialeRace:true,x:q.x,z:q.z,yaw,width,length,rise,baseY,topY:[baseY,baseY,baseY+rise,baseY+rise],boostPad:{x:q.x-s*behind,z:q.z-c*behind,yaw,width:width*.92,length:5.2,used:false}};}
function buildFakeRamp(game,r,index,side){const p=r.samples[index],yaw=yawAt(r.samples,index),q=lateral(p,yaw,side*.9);return {kind:'tangenziale-race-fake-ramp',tangenzialeRaceFake:true,index,x:q.x,z:q.z,yaw,width:5.4,length:8.5,rise:.28,baseY:heightAt(game,p,q.x,q.z),lastHit:-Infinity};}
function enlargeRaceMap(){if(typeof document==='undefined')return;const box=document.getElementById('tangenzialeCourseBox'),canvas=document.getElementById('tangenzialeCourseMap');if(box){box.style.width='330px';box.style.padding='11px 12px 10px';}if(canvas){canvas.width=304;canvas.height=196;canvas.style.width='304px';canvas.style.height='196px';}}
function configure(manager){const r=manager.race,g=manager.game;if(!r||r.__shortSprint)return;r.__shortSprint=true;const target=Math.min(TARGET_METRES,r.total);if(r.total>MIN_METRES&&target<r.total-120){let finishIndex=r.startIndex+1;for(let i=r.startIndex+1;i<r.samples.length-1;i++){finishIndex=i;if(progress(r,i)>=target)break;}finishIndex=safeIndex(r.samples,r.startIndex,finishIndex,1);const old=r.samples,trim=old.slice(0,finishIndex+1);trim.cumulative=old.cumulative.slice(0,finishIndex+1);trim.total=trim.cumulative.at(-1)||0;r.samples=trim;r.finish=trim.at(-1);r.finishYaw=yawAt(trim,trim.length-1);r.total=Math.max(1,progress(r,trim.length-1));if(r.finishSet){r.finishSet.position.set(r.finish.x,heightAt(g,r.finish),r.finish.z);r.finishSet.rotation.y=r.finishYaw;}g.state.waypoint={x:r.finish.x,z:r.finish.z,name:'TRAGUARDO · Sprint tangenziale'};g.state.route=trim.slice(r.startIndex).map(p=>({x:p.x,z:p.z}));}
 const end=r.samples.length-1;for(let i=0;i<r.obstacleDefs.length;i++){const def=r.obstacleDefs[i],car=r.obstacles[i],idx=safeIndex(r.samples,r.startIndex,end,OBSTACLE_FRACTIONS[i]);def.index=idx;const p=r.samples[idx],baseYaw=yawAt(r.samples,idx),q=lateral(p,baseYaw,def.offset||0);Object.assign(car,{x:q.x,z:q.z,y:heightAt(g,p,q.x,q.z),yaw:baseYaw+(def.yawOffset||0),speed:0,parked:true,budgetSleeping:false,missionUnit:true,fixedSpawn:true});car.mesh.visible=true;g.pose(car);}for(const c of r.ai)c.path=offsetPath(r.samples,c.raceOffset||0,r.obstacleDefs);
 g.terrain.arcadeRamps=(g.terrain.arcadeRamps||[]).filter(x=>!x.tangenzialeRace);for(const root of r.roots.filter(x=>/tangenziale-(race-ramps|bridge-jump-ramps|race-boost-pads)/.test(x?.name||'')))g.scene.remove(root);const root=new THREE.Group();root.name='tangenziale-short-sprint-ramps';r.ramps=[];r.fakeRamps=[];for(const [i,f] of HIGH_RAMP_FRACTIONS.entries()){const idx=safeIndex(r.samples,r.startIndex,end,f),ramp=buildHighRamp(g,r,idx,i%2?-1:1);r.ramps.push(ramp);g.terrain.arcadeRamps.push(ramp);rampVisual(root,ramp,false);}for(const [i,f] of FAKE_RAMP_FRACTIONS.entries()){const idx=safeIndex(r.samples,r.startIndex,end,f),trap=buildFakeRamp(g,r,idx,i%2?1:-1);r.fakeRamps.push(trap);rampVisual(root,trap,true);}g.scene.add(root);r.roots.push(root);queueMicrotask(enlargeRaceMap);g.toast('SPRINT TANGENZIALE · circa 2 minuti · rampe alte e rampe trappola.',4);}
function applyFakeRamp(manager,r){const s=manager.game.state;if(r.playerFinished)return;for(const trap of r.fakeRamps||[]){const dx=s.x-trap.x,dz=s.z-trap.z,u=dx*Math.cos(trap.yaw)-dz*Math.sin(trap.yaw),v=dx*Math.sin(trap.yaw)+dz*Math.cos(trap.yaw);if(Math.abs(u)>trap.width/2||Math.abs(v)>trap.length/2||s.elapsed-trap.lastHit<1.4)continue;trap.lastHit=s.elapsed;s.speed*=.42;r.playerCar.speed=s.speed;manager.game.toast('RAMPA TRAPPOLA · forte perdita di velocità!',1.6);break;}}
function enforceTrack(manager,r){if(r.playerFinished)return;const p=nearest2D(manager.game.state,r.samples,r.playerHint||r.startIndex);if(p.d<=OFFROAD_LIMIT)return;manager.respawnActor(r.playerCar,r.playerCheckpoint??r.startIndex,-1.2);manager.game.toast('Fuori strada · respawn immediato in pista.',1.8);}

const BASE_START=TangenzialeRace.prototype.start,BASE_UPDATE=TangenzialeRace.prototype.update;
if(!TangenzialeRace.prototype.__shortSprint){TangenzialeRace.prototype.__shortSprint=true;TangenzialeRace.prototype.start=function(...args){const out=BASE_START.apply(this,args);if(this.race)configure(this);return out;};TangenzialeRace.prototype.update=function(dt){if(this.race&&!this.race.__shortSprint)configure(this);const out=BASE_UPDATE.call(this,dt),r=this.race;if(r?.phase==='running'){enforceTrack(this,r);applyFakeRamp(this,r);enlargeRaceMap();}return out;};}

export const SHORT_SPRINT={targetMetres:TARGET_METRES,minMetres:MIN_METRES,offroadLimit:OFFROAD_LIMIT,highRamps:HIGH_RAMP_FRACTIONS.length,fakeRamps:FAKE_RAMP_FRACTIONS.length};
